import re,subprocess,tarfile,json
from pathlib import Path
pat=re.compile(rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|gh[pousr]_[A-Za-z0-9]{30,}|sk-(?:proj-)?[A-Za-z0-9_-]{32,}')
files=subprocess.check_output(['git','diff','--name-only','origin/main','--','.'],text=True).splitlines()
findings=[]
for n in files:
 p=Path(n)
 if not p.is_file():continue
 if n.endswith('.tar.gz'):
  with tarfile.open(p) as t:
   for m in t.getmembers():
    if m.isfile() and pat.search(t.extractfile(m).read()):findings.append(n+':'+m.name)
 elif pat.search(p.read_bytes()):findings.append(n)
print(json.dumps({'scannedChangedFiles':len(files),'credentialPatternMatches':findings}))
